#include "n0te_ring.h"
int n0te_ring_init(n0te_ring*r,float*memory,size_t capacity){if(!r||!memory||capacity<2)return 0;r->data=memory;r->capacity=capacity;atomic_init(&r->read_index,0);atomic_init(&r->write_index,0);atomic_init(&r->sequence,0);atomic_init(&r->overruns,0);atomic_init(&r->underruns,0);return 1;}
size_t n0te_ring_write(n0te_ring*r,const float*input,size_t count){size_t written=0;while(written<count){size_t w=atomic_load_explicit(&r->write_index,memory_order_relaxed);size_t next=(w+1)%r->capacity;if(next==atomic_load_explicit(&r->read_index,memory_order_acquire)){atomic_fetch_add(&r->overruns,1);break;}r->data[w]=input[written++];atomic_store_explicit(&r->write_index,next,memory_order_release);}if(written)atomic_fetch_add(&r->sequence,1);return written;}
size_t n0te_ring_read(n0te_ring*r,float*output,size_t count){size_t read=0;while(read<count){size_t current=atomic_load_explicit(&r->read_index,memory_order_relaxed);if(current==atomic_load_explicit(&r->write_index,memory_order_acquire)){atomic_fetch_add(&r->underruns,1);break;}output[read++]=r->data[current];atomic_store_explicit(&r->read_index,(current+1)%r->capacity,memory_order_release);}return read;}
void n0te_ring_reset(n0te_ring*r){atomic_store(&r->read_index,0);atomic_store(&r->write_index,0);atomic_store(&r->sequence,0);atomic_store(&r->overruns,0);atomic_store(&r->underruns,0);}
